impl RunResult {
    /// Measures this variant's wire encoding.
    #[must_use]
    pub fn measure(&self) -> u32 {
        match self {
            Self::Accepted(record) => 1_u32.checked_add(Accepted::measure(record)).expect("schema ceilings fit u32"),
            Self::Failed(record) => 1_u32.checked_add(Failed::measure(record)).expect("schema ceilings fit u32"),
            Self::Refused(record) => 1_u32.checked_add(Refused::measure(record)).expect("schema ceilings fit u32"),
            Self::Parked => 1,
        }
    }

    /// Writes this variant's tag and payload.
    pub fn encode(&self, writer: &mut skein_lib::Writer) -> Result<(), skein_lib::Overflow> {
        match self {
            Self::Accepted(record) => { writer.put(&[0_u8])?; record.encode(writer)?; }
            Self::Parked => writer.put(&[1_u8])?,
            Self::Failed(record) => { writer.put(&[2_u8])?; record.encode(writer)?; }
            Self::Refused(record) => { writer.put(&[3_u8])?; record.encode(writer)?; }
        }
        Ok(())
    }

    /// Reads a whole variant and refuses trailing bytes.
    pub fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::decode_from(limits, reader)?;
        if !reader.is_empty() { return Err(Problem { path: Path::RunResultTag, reason: skein_codec::Reason::Trailing }); }
        Ok(value)
    }

    fn decode_from(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: Path::RunResultTag, reason: skein_codec::Reason::Short })?;
        let value = match tag {
            0 => Self::Accepted(Accepted::decode_from(limits, reader)?),
            1 => Self::Parked,
            2 => Self::Failed(Failed::decode_from(limits, reader)?),
            3 => Self::Refused(Refused::decode_from(limits, reader)?),
            _ => return Err(Problem { path: Path::RunResultTag, reason: skein_codec::Reason::Tag }),
        };
        Ok(value)
    }
}

